const room=new URLSearchParams(location.search).get('p')||'main';
const roomPath=p=>p+(room==='main'?'':(p.includes('?')?'&':'?')+'p='+encodeURIComponent(room));
const joinUrl=new URL(roomPath('/join'),location.origin).href;
let libraryItems=null,libraryError='',newDeckOpen=false;
