const joinQr=qrSvg(joinUrl);const activityTypes=['poll','rating','wordcloud','qa','countdown'];const slideTypes={standard:'Standard slide',competition:'Competition / voting',join:'QR code / Join session',poll:'Multiple choice',rating:'Rating',wordcloud:'Word cloud',qa:'Q&A',countdown:'Standalone countdown',results:'Competition results',video:'Linked video'};
const app=document.querySelector('#app'),path=location.pathname,mode=path.startsWith('/tv/')?'tv':path==='/join'?'join':path==='/control'?'control':path==='/library'?'library':'admin';
