// Editor-only drag interactions. Existing slide IDs and stored percentage fields are preserved.
function decorateLogos(){
 if(mode!=='admin')return;
 for(const [selector,mobile] of [['#preview .slide',false],['#phone-preview .phone-screen',true]]){
  const canvas=document.querySelector(selector);if(!canvas)continue;
  const logo=canvas.querySelector(mobile?'.phone-brand:has(img)':':scope > img');if(!logo||canvas.querySelector('.logo-editor'))continue;
  const frame=document.createElement('div');frame.className='logo-editor';frame.dataset.mobile=String(mobile);frame.tabIndex=0;frame.setAttribute('aria-label','Move logo with arrow keys; Shift + arrow keys moves faster');
  const handle=document.createElement('button');handle.type='button';handle.className='logo-resize';handle.setAttribute('aria-label','Resize logo');handle.title='Drag to resize';
  if(mobile){logo.classList.add('editable-brand');logo.append(frame);frame.append(handle);}else{logo.before(frame);frame.append(logo,handle);}
  const img=frame.querySelector('img')||logo.querySelector('img');if(img)img.draggable=false;
 }
}
function markLayoutDirty(){dirty=true;const status=document.querySelector('#save-status');if(status)status.textContent='Unsaved changes';}
