let slideDrag=null;
function dropMarker(e){const row=e.target.closest('.slide-item');if(!row)return null;return {row,after:e.clientY>row.getBoundingClientRect().top+row.getBoundingClientRect().height/2};}
function clearMarkers(){app.querySelectorAll('.drop-before,.drop-after').forEach(n=>n.classList.remove('drop-before','drop-after'));}
app.addEventListener('dragstart',e=>{const row=e.target.closest('.slide-item');if(mode!=='admin'||!row||!draft)return;slideDrag=row.dataset.slideId;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',slideDrag);row.classList.add('dragging');});
app.addEventListener('dragover',e=>{if(!slideDrag)return;const hit=dropMarker(e);if(!hit)return;e.preventDefault();e.dataTransfer.dropEffect='move';clearMarkers();if(hit.row.dataset.slideId!==slideDrag)hit.row.classList.add(hit.after?'drop-after':'drop-before');});
