function logoVars(m){return m?['mobileLogoX','mobileLogoY','mobileLogoSize','--mobile-logo-x','--mobile-logo-y','--mobile-logo-width',50,9,50,5,90]:['logoX','logoY','logoSize','--logo-x','--logo-y','--logo-width',85,12,19,3,70];}
