app.addEventListener('keydown',e=>{const frame=e.target.closest('.logo-editor');if(!frame||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||!draft)return;e.preventDefault();const m=frame.dataset.mobile==='true',s=draft.slides[selected],v=logoVars(m),delta=e.shiftKey?5:1;setLogo(frame.closest(m?'.phone-screen':'.slide'),s,m,num(s[v[0]],v[6])+delta*((e.key==='ArrowRight')-(e.key==='ArrowLeft')),num(s[v[1]],v[7])+delta*((e.key==='ArrowDown')-(e.key==='ArrowUp')),num(s[v[2]],v[8],v[9],v[10]));refreshLogoThumb();});

