function applyNumeric(t,commit=false){if(!draft||mode!=='admin')return;const k=t.dataset.number;if(!k)return;const s=draft.slides[selected],lo=Number(t.min),hi=Number(t.max);if(!commit&&(t.value===''||!Number.isFinite(t.valueAsNumber)||t.valueAsNumber<lo||t.valueAsNumber>hi))return;const value=['duration','ratingMax','voteDuration'].includes(k)?Math.round(num(t.value,s[k]??Number(t.defaultValue),lo,hi)):Math.round(num(t.value,s[k]??Number(t.defaultValue),lo,hi)*10)/10;if(commit)t.value=value;s[k]=value;const slider=app.querySelector(`input[type="range"][data-prop="${k}"]`);if(slider)slider.value=value;markLayoutDirty();updatePhonePreview();refreshLogoThumb();}
